"""Experimental, planar, equal-distance biarcs with analytic arc stationing.

The authored controls and bisector tangents match the established cubic method.
Each span uses two exact circular arcs (a straight line is the zero-curvature
limit), with a shared tangent at their join. The returned POLY curve is an
internal one-dimensional arc-length carrier, NOT an approximation to the road:
its points lie at exact cumulative arc lengths and hold original XY positions,
tangents and per-span arc parameters. Downstream frames evaluate arcs directly.
Exact-polyline mode returns the unchanged authored polyline instead.

Circular curvature is constant, so reach*abs(curvature)<.98 certifies the whole
arc without curvature probes. Existing quad and complete perimeter guards are
still required. Forward, minor-arc solutions only; degeneracy is rejected.
"""
from . import path_station_nodes

OFFSET_JACOBIAN_MARGIN = .02


def _sinc(g, angle):
    square = g.math('MULTIPLY', angle, angle)
    series = g.math('ADD', g.math('SUBTRACT', 1., g.math('DIVIDE', square, 6.)),
                    g.math('DIVIDE', g.math('MULTIPLY', square, square), 120.))
    return g.switch(g.compare(g.math('ABSOLUTE', angle), .001, 'LESS_THAN'),
                    g.math('DIVIDE', g.math('SINE', angle), angle), series)


def _left(g, tangent):
    return g.vector('CROSS_PRODUCT', (0., 0., 1.), tangent)


def _arc(g, tangent, chord):
    """Start-tangent arc to a chord endpoint: signed curvature and true length."""
    x = g.vector('DOT_PRODUCT', tangent, chord)
    y = g.vector('DOT_PRODUCT', _left(g, tangent), chord)
    half_angle = g.math('ARCTAN2', y, x)
    square = g.vector('DOT_PRODUCT', chord, chord)
    curvature = g.math('DIVIDE', g.math('MULTIPLY', 2., y), g.math('MAXIMUM', square, 1.e-16))
    length = g.math('DIVIDE', g.vector('LENGTH', chord), _sinc(g, half_angle))
    forward = g.compare(x, 1.e-6, 'GREATER_THAN')
    return curvature, length, forward


def _frame(g, start, tangent, curvature, distance):
    angle = g.math('MULTIPLY', curvature, distance)
    along = g.math('MULTIPLY', distance, _sinc(g, angle))
    half = g.math('MULTIPLY', .5, angle)
    half_sinc = _sinc(g, half)
    across = g.math('MULTIPLY', g.math('MULTIPLY', distance, half),
                    g.math('MULTIPLY', half_sinc, half_sinc))
    normal = _left(g, tangent)
    point = g.vector('ADD', start, g.vector('ADD',
        g.vector('SCALE', tangent, along), g.vector('SCALE', normal, across)))
    direction = g.vector('ADD', g.vector('SCALE', tangent, g.math('COSINE', angle)),
                          g.vector('SCALE', normal, g.math('SINE', angle)))
    return point, direction


def construct(g, polyline, degree, width, offset, endpoint_tangents):
    index = g.node('GeometryNodeInputIndex', 'Biarc authored knot index').outputs[0]
    position = g.node('GeometryNodeInputPosition', 'Biarc authored control').outputs[0]
    size = g.node('GeometryNodeAttributeDomainSize', 'Biarc control domain')
    size.component = 'CURVE'
    g.set(polyline, size.inputs['Geometry'])
    n = size.outputs['Point Count']
    last = g.math('SUBTRACT', n, 1.)
    first = g.compare(index, 0, kind='INT')
    final = g.compare(index, last, kind='INT')
    previous = g.sample(polyline, position, g.math('MAXIMUM', 0., g.math('SUBTRACT', index, 1.)), 'FLOAT_VECTOR')
    following = g.sample(polyline, position, g.math('MINIMUM', last, g.math('ADD', index, 1.)), 'FLOAT_VECTOR')
    incoming = g.vector('SUBTRACT', position, previous)
    outgoing = g.vector('SUBTRACT', following, position)
    tangent = g.vector('NORMALIZE', g.vector('ADD', g.vector('NORMALIZE', incoming), g.vector('NORMALIZE', outgoing)))
    tangent = g.switch(first, tangent, g.vector('NORMALIZE', endpoint_tangents[0]), 'VECTOR')
    tangent = g.switch(final, tangent, g.vector('NORMALIZE', endpoint_tangents[1]), 'VECTOR')
    common = g.all(g.compare(n, 2, 'GREATER_EQUAL', 'INT'),
        g.compare(size.outputs['Spline Count'], 1, kind='INT'), g.compare(width, 0., 'GREATER_THAN'),
        g.stat(polyline, g.all(g.either(first, g.compare(g.vector('LENGTH', incoming), 1.e-4, 'GREATER_THAN')),
                              g.either(final, g.compare(g.vector('LENGTH', outgoing), 1.e-4, 'GREATER_THAN')))))
    recorded = g.store(polyline, 'st_biarc_point', position, 'FLOAT_VECTOR')
    recorded = g.store(recorded, 'st_curve_tangent', tangent, 'FLOAT_VECTOR')
    recorded = g.store(recorded, 'st_knot_index', index, 'INT')
    t0 = g.named('st_curve_tangent', 'FLOAT_VECTOR')
    t1 = g.sample(recorded, t0, g.math('MINIMUM', last, g.math('ADD', index, 1.)), 'FLOAT_VECTOR')
    v = outgoing
    v2 = g.vector('DOT_PRODUCT', v, v)
    b = g.vector('DOT_PRODUCT', v, g.vector('ADD', t0, t1))
    a = g.math('MULTIPLY', 2., g.math('MAXIMUM', 0., g.math('SUBTRACT', 1., g.vector('DOT_PRODUCT', t0, t1))))
    discriminant = g.math('ADD', g.math('MULTIPLY', b, b), g.math('MULTIPLY', a, v2))
    # Rationalized positive root also covers equal, forward-pointing tangents.
    d = g.math('DIVIDE', v2, g.math('MAXIMUM', 1.e-12, g.math('ADD', b, g.math('SQRT', discriminant))))
    half_v = g.vector('SCALE', v, .5)
    shift = g.vector('SCALE', g.vector('SUBTRACT', t0, t1), g.math('MULTIPLY', .5, d))
    chord_a = g.vector('ADD', half_v, shift)
    chord_b = g.vector('SUBTRACT', shift, half_v)
    reverse_t1 = g.vector('SCALE', t1, -1.)
    ka, la, forward_a = _arc(g, t0, chord_a)
    kb, lb, forward_b = _arc(g, reverse_t1, chord_b)
    _pa, ta = _frame(g, (0., 0., 0.), t0, ka, la)
    _pb, tb = _frame(g, (0., 0., 0.), reverse_t1, kb, lb)
    reach = g.math('ADD', g.math('ABSOLUTE', offset), g.math('MULTIPLY', .5, width))
    curvature = g.math('MAXIMUM', g.math('ABSOLUTE', ka), g.math('ABSOLUTE', kb))
    span_ok = g.all(forward_a, forward_b,
        g.compare(g.vector('DOT_PRODUCT', g.vector('NORMALIZE', v), t0), 1.e-5, 'GREATER_THAN'),
        g.compare(g.vector('DOT_PRODUCT', g.vector('NORMALIZE', v), t1), 1.e-5, 'GREATER_THAN'),
        g.compare(g.vector('LENGTH', g.vector('ADD', ta, tb)), 5.e-5, 'LESS_THAN'),
        g.compare(g.math('MULTIPLY', reach, curvature), 1.-OFFSET_JACOBIAN_MARGIN, 'LESS_THAN'),
        g.compare(g.math('ADD', la, lb), 1.e6, 'LESS_THAN'))
    smooth_ok = g.all(g.stat(recorded, g.either(final, span_ok)),
        g.stat(recorded, g.compare(g.vector('LENGTH', t0), .99, 'GREATER_THAN')),
        g.compare(g.vector('LENGTH', endpoint_tangents[0]), 1.e-5, 'GREATER_THAN'),
        g.compare(g.vector('LENGTH', endpoint_tangents[1]), 1.e-5, 'GREATER_THAN'))
    for name, value in (('ka', ka), ('kb', kb), ('la', la), ('lb', lb)):
        recorded = g.store(recorded, 'st_biarc_'+name, value)
    span_length = g.switch(final, g.math('ADD', g.named('st_biarc_la', 'FLOAT'), g.named('st_biarc_lb', 'FLOAT')), 0.)
    prefix = g.node('GeometryNodeAccumulateField', 'Analytic biarc length prefixes, no evaluated curve sampling')
    prefix.data_type = 'FLOAT'
    prefix.domain = 'POINT'
    g.set(span_length, prefix.inputs['Value'])
    place = g.node('GeometryNodeSetPosition', 'Internal scalar arc-length carrier, original XY retained in attributes')
    g.set(recorded, place.inputs['Geometry'])
    g.set(g.xyz(prefix.outputs['Trailing']), place.inputs['Position'])
    smooth = g.compare(degree, 3, kind='INT')
    exact = g.compare(degree, 0, kind='INT')
    valid = g.all(common, g.either(exact, smooth), g.switch(smooth, True, smooth_ok, 'BOOLEAN'))
    return g.switch(smooth, recorded, place.outputs['Geometry'], 'GEOMETRY'), valid


def evaluated_frame(g, curves, path_index, t):
    selected, count, _length, _valid = path_station_nodes._selected_curve(g, curves, path_index, 'Biarc frame')
    rank = g.math('MULTIPLY', g.math('MAXIMUM', 0., g.math('MINIMUM', 1., t)), g.math('SUBTRACT', count, 1.))
    segment = g.math('MINIMUM', g.math('FLOOR', rank), g.math('SUBTRACT', count, 2.))
    alpha = g.math('SUBTRACT', rank, segment)
    def sample(name, kind='FLOAT', at=segment):
        return g.sample(selected, g.named(name, kind), at, kind)
    start = sample('st_biarc_point', 'FLOAT_VECTOR')
    end = sample('st_biarc_point', 'FLOAT_VECTOR', g.math('ADD', segment, 1.))
    t0 = sample('st_curve_tangent', 'FLOAT_VECTOR')
    t1 = sample('st_curve_tangent', 'FLOAT_VECTOR', g.math('ADD', segment, 1.))
    ka, kb, la, lb = [sample('st_biarc_'+key) for key in ('ka', 'kb', 'la', 'lb')]
    distance = g.math('MULTIPLY', alpha, g.math('ADD', la, lb))
    second = g.compare(distance, la, 'GREATER_THAN')
    origin = g.switch(second, start, end, 'VECTOR')
    direction = g.switch(second, t0, g.vector('SCALE', t1, -1.), 'VECTOR')
    curvature = g.switch(second, ka, kb)
    along = g.switch(second, distance, g.math('SUBTRACT', g.math('ADD', la, lb), distance))
    point, tangent = _frame(g, origin, direction, curvature, along)
    tangent = g.switch(second, tangent, g.vector('SCALE', tangent, -1.), 'VECTOR')
    # Snap authored knots exactly, including the last one, as in cubic mode.
    # Compare-node EQUAL has a nonzero epsilon by default. Using it here would
    # collapse distinct rows near a knot (notably in unequal paired station
    # unions). Snap only the exact bounded endpoints, with no tolerance band.
    at_knot = g.compare(alpha, 0., 'LESS_EQUAL')
    at_end = g.compare(alpha, 1., 'GREATER_EQUAL')
    point = g.switch(at_knot, point, start, 'VECTOR')
    point = g.switch(at_end, point, end, 'VECTOR')
    tangent = g.switch(at_knot, tangent, t0, 'VECTOR')
    tangent = g.switch(at_end, tangent, t1, 'VECTOR')
    poly = g.node('GeometryNodeSampleCurve', 'Unchanged exact-polyline frame')
    poly.data_type = 'FLOAT_VECTOR'
    poly.mode = 'FACTOR'
    g.set(selected, poly.inputs['Curves'])
    g.set(path_station_nodes._factor(g, selected, count, t), poly.inputs['Factor'])
    g.set(g.named('st_poly_miter', 'FLOAT_VECTOR'), poly.inputs['Value'])
    smooth = g.compare(g.sample(selected, g.named('st_sweep_interpolation'), 0, 'INT', 'CURVE'), 3, kind='INT')
    return (g.switch(smooth, poly.outputs['Position'], point, 'VECTOR'),
            g.switch(smooth, poly.outputs['Value'], g.right(tangent), 'VECTOR'))
